const COCKPIT_SEAT=Object.freeze({version:1,room:Object.freeze([1.1,.7,1.2])});
const DROID_BRAIN_D=.34,COCKPIT_SEAT_D=Math.cbrt(COCKPIT_SEAT.room.reduce((a,b)=>a*b,1));
addComp('cockpit','要員区画（座席）','cube',0.35,[132,200,232],'craft','乗員1名が座る区画（幅0.7 m・高さ1.2 m・奥行1.1 m で固定）。切り抜きも変形もできない内装で、構造物の中に完全に収めて置きます。収まった区画の数が乗員になります（寝起きは母艦）。乗員を増やすときは区画を増やしてください。',{def:COCKPIT_SEAT_D,min:COCKPIT_SEAT_D,max:COCKPIT_SEAT_D,crew:0,cost:2,hp:.5});
function normalizeCockpitSeat(p){
 if(p?.k!=='cockpit')return p;
 p.room=COCKPIT_SEAT.room.slice();p.d=COCKPIT_SEAT_D;p.seats=1;p.corner=0;
 for(const key of ['canopy','pitch','roll','surfaceNormal','_canopyBody'])delete p[key];
 return p;
}
// A cockpit seat counts only when a whole seated person fits inside the hull.
// Stock builders: move each seat or bomb bay that sticks out of the structures to the nearest position where it
// lies wholly inside them, clear of the other equipment (search within 1 m, 2.5 cm steps, nearest first).
function uncutRoomInside(ship,p){const b=partAABB(p);for(const u of [0,.25,.5,.75,1])for(const v of [0,.25,.5,.75,1])for(const w of [0,.25,.5,.75,1])if(!insideOriginalEnvelope(ship,[lerp(b[0],b[3],u),lerp(b[1],b[4],v),lerp(b[2],b[5],w)]))return false;return true;}
function settleUncutRooms(ship,kinds=['cockpit','bombBay'],test=null,opts={}){
 const steps=[];for(let x=-40;x<=40;x++)for(let y=-40;y<=40;y++)for(let z=-40;z<=40;z++)steps.push([x*.025,y*.025,z*.025]);steps.sort((a,b)=>dot(a,a)-dot(b,b));
 const moved=[];
 for(const p of ship.parts.filter(q=>kinds.includes(q.k))){
  const home=p.c.slice(),others=()=>ship.parts.filter(q=>q!==p&&!isShapePart(q)),ok=()=>uncutRoomInside(ship,p)&&!others().some(q=>overlapParts(p,q))&&(!test||test(p));
  if(ok())continue;let found=false;
  for(const d of steps){if(Math.abs(p.c[2])<1e-9&&Math.abs(d[2])>1e-9)continue;p.c=add(home,d);delete p._roomShape;if(ok()){found=true;moved.push(p.id);break;}}
  if(!found){p.c=home;delete p._roomShape;
   // A stock cockpit whose airframe cannot hold a seated crew member gets a canopy structure over the seat
   // (a tinted box 6 cm larger than the seat on every side), as the old cockpit sphere stood for the canopy.
   if(p.k==='cockpit'&&opts.canopy!==false){const r=COCKPIT_SEAT.room,shell={id:ship.nextId++,k:'struct',c:home.slice(),s:[r[0]+.12,r[1]+.12,r[2]+.12],form:'trap',taper:0,yaw:0,offsetX:0,offsetZ:0,pitch:0,roll:0,corner:.08,label:'キャノピー（座席区画）',paint:'#2e3e4a',skin:'plain',light:true};ship.parts.push(shell);delete ship._clipEnvelope;
    if(ok()){moved.push(p.id);continue;}
    for(const d of steps){if(Math.abs(d[0])>.3||Math.abs(d[1])>.3||Math.abs(home[2])<1e-9&&Math.abs(d[2])>1e-9)continue;p.c=add(home,d);shell.c=p.c.slice();delete p._roomShape;delete shell._shape;delete ship._clipEnvelope;if(ok()){found=true;moved.push(p.id);break;}}
    if(!found){p.c=home;shell.c=home.slice();delete p._roomShape;}}
  }
 }
 return moved;
}
function cockpitSeatFits(p){return p?.k==='cockpit'&&Array.isArray(p.room)&&p._seatOutside!==true;}
// Saved designs from before v24: an editable canopy (or a sphere) with N seats becomes the canopy's
// appearance as a structure plus N seat rooms at its centre, the extra ones one seat apart aft.
function migrateCockpitSeats(ship){
 for(const p of ship.parts)if(p.k==='droidbrain'){p.d=DROID_BRAIN_D;delete p.room;}
 const legacy=ship.parts.filter(p=>p.k==='cockpit'&&(!Array.isArray(p.room)||p.canopy||(p.seats||1)>1));
 for(const p of legacy){
  const seats=clamp(Math.round(p.seats||1),1,20),body=!Array.isArray(p.room)||p.canopy?canopyBody({...p,canopy:canopyShape(p)}):null;
  if(body){const shell=JSON.parse(JSON.stringify(body));Object.assign(shell,{id:ship.nextId++,label:'キャノピー',paint:'#2e3e4a',skin:'plain',light:true});ship.parts.push(shell);}
  const suit=p.suit===true;normalizeCockpitSeat(p);
  for(let i=1;i<seats;i++){const q=normalizeCockpitSeat({id:ship.nextId++,k:'cockpit',c:[p.c[0]-COCKPIT_SEAT.room[0]*i,p.c[1],p.c[2]],label:p.label});if(suit)q.suit=true;ship.parts.push(q);}
 }
 return legacy.length;
}

