     room('service',label+'航空整備甲板・上層',[cx,90,sg*mid],[x1-x0,w,42],{outline});
     const notch=[[x0,ia],[x1,ib],[x1,300],[774,300],[774,100],[752,100],[752,300],[x0,300]].map(([x,z])=>[(x-cx)/(x1-x0),sg*(z-mid)/w]);
