const GROUND_PRESETS=Object.freeze([{name:'歩兵部隊',kind:'troops',size:1},{name:'B1バトル・ドロイド（停止保管）',kind:'droids',size:1},{name:'車両（機種を選ぶ）',kind:'vehicle',type:'atat'}]);
