  k.loftX('背部砲塔塔の上部',[[35.5,15.1,23.5,121.5,128.5],[40,15.1,23.5,121.5,131],[45,15.1,23.5,121.5,131.4],[51,15.1,23.5,121.5,127]],{corner:.25,...W});
