  k.loftX('連結桁の基部',[[52,-2.9,2.9,94.6,105],[56,-5.3,5.3,87.4,105],[63.5,-5.3,5.3,87.4,105],[67,-4.4,4.4,89.2,105],[70.5,-2.9,2.9,96.6,105],[84,-2.9,2.9,96.6,105],[86,-2,2,98.6,105]],{corner:.15,...W});
