// v19 Separatist livery (CIS_PAINT); the Invisible Hand's subtle yellow bow stripes are bands.
const PROV_GLASS='#2b3238',PROV_GREY=CIS_PAINT.grey,PROV_PANEL=CIS_PAINT.panel,PROV_STEEL=CIS_PAINT.steel,PROV_DARK=CIS_PAINT.dark,PROV_PLATE='#b3bac3',PROV_SLATE=CIS_PAINT.slate;
// opt.scale 1 builds the carrier/destroyer, PROV_DN_K the dreadnought.
const PROV_DN_K=2177.35/1088;
function providenceBuild(opt={}){
 const K=opt.scale||1,dn=K!==1,D=PROV,L=1088*K,SY=.928,Y=v=>v*SY*K,M=v=>v*K;
 // v24 The hull structure is the measured main body only (12.8-100% of the length): the thread-thin
 // section that ran it back to the stern is gone; the engine block there is measured structure.
 const s=centralHullShip({L,W:D.W*K,H:D.H*K,sec:'warship',plan:'wedge',deckWidth:0,keelWidth:0,belt:.13,chineHeight:.5,bowFree:true,stations:D.st.map(a=>a.slice())},.128,1,dn?'プロヴィデンス級ドレッドノート':'プロヴィデンス級キャリア／デストロイヤー');
 s._building=true;s.reference=dn?'providenceDn':'providence';s.paint='cis';s.lights='warm';s.detail=1;s.armor=dn?{hull:.65*3,cit:.35*3}:{hull:.65,cit:.35};/* v18 a dreadnought carries three times the plating: slower than the base ship, far tougher */s.shieldTarget=1;
 const k=shipKit(s),part=(kind,label,c,d,o={})=>placePart(s,kind,c,d,{label,...o});
 // v24 The hull (stations) is fitted to the model's main body solids; every
 // other solid of the supplied Invisible_Hand.stl is a measured loft.
 s.hullBands=[[.886,.892,CIS_PAINT.gold],[.899,.905,CIS_PAINT.gold]];
 buildMeasuredSolids(s,k,D.parts,{L,scale:K,paint:PROV_PANEL,roundPaint:PROV_STEEL,nextId:24});
 // ---- aft half: the expansive hangar decks in the measured through-slot (open on both beams) ----
 // v24 The through-slot of the model is x 297-420 m, 133-148 m up in the measuring frame (before the 0.928
 // height scale), open from beam to beam (outer skin |z| 114 m): the deck fills it, and its two beam mouths
 // are the ray-shielded hangar openings.
 const dock=part('hangar','後部格納甲板（舷側貫通発着口）',[M(358.5),Y(140.5),0],M(30),{room:[M(123),M(228),M(15)],airRole:'mixed'});
 openBay(s,dock,'port','ray');openBay(s,dock,'stbd','ray');
 if(opt.stage==='dock'){delete s._building;return s;}
 // ---- stern: auxiliary reactor for the radial ion drives; port-side hyperdrive module ----
 const ra=part('aux','艦尾補助炉',[M(216),Y(120),0],M(100));
 const eo=equipmentOptions('exposedTurbine');
 const engine=(label,mouth,y,z,d,body,mirror)=>{const nl=engineBaseline('exposed',d,'nozzleLength'),len=engineBaseline('exposed',d,'length')*body/engineBaseline('exposed',d,'body');const p=placePart(s,'engine',[mouth+nl/2,y,z],d,{...eo,label,d,reactor:ra.id,dir:[-1,0,0],engineLength:len},mirror);resizeEngine(p,d,len);return p;};
 engine('中央主機（ヌビアン・クレヴェルド4放射状イオン機関）',M(10.3),Y(122.3),0,M(34),engineBaseline('exposed',M(34),'body'),false);
 engine('舷側主機（ヌビアン・クレヴェルド4放射状イオン機関）',M(18.6),Y(112.2),M(43.35),M(54),engineBaseline('exposed',M(54),'body'),true);
 part('hyper','左舷ハイパードライブ・モジュール',[M(240),Y(160),M(-60)],M(24),{length:M(70)});
 // ---- bow: main and subsidiary reactors, the deflector shield generator network,
 //      the hyperdrive reactant silo and compressed reactant tank; mid: inertial compensator ----
 part('gen','主反応炉（艦首）',[M(760),Y(116),0],M(56));
 part('aux','副反応炉（艦首）',[M(880),Y(114),0],M(40));
 for(const sg of [-1,1])part('shield','偏向シールド発生器網',[M(820),Y(114),M(sg*30)],M(28));
 for(const sg of [-1,1])part('fuel','ハイパードライブ反応物サイロ／圧縮反応物タンク',[M(680),Y(114),M(sg*36)],M(22),{length:M(30),dir:[0,1,0]});
 part('inertial','慣性補償装置',[M(600),Y(118),0],M(34),{length:M(70)});
 if(opt.stage==='machinery'){delete s._building;return s;}
 // Heavy guns keep their charging plant wholly inside the envelope and clear of
 // machinery: the plant is pushed deeper until all its corners are enclosed.
 let solidList=null;
 const plantFits=f=>{if(!needsCapacitor(f))return true;const q=weaponChargeSpec(f),depth=12,side=Math.sqrt(q.targetVolume/depth),up=fitUp(f),fr=frameAxis(up);solidList=solidList||allOccupied(s).map(p=>({p,b:partAABB(p)}));
  for(const cd of [10,13,16,20,24,28,33,38,44]){const c=sub(f.p,mul(up,cd+(f.mountOffset||0)));let ok=true;
   for(const a of [-.5,0,.5])for(const b of [-.5,0,.5])for(const e of [-.5,0,.5]){const pt=add(c,add(mul(up,a*depth),add(mul(fr.v,b*side),mul(fr.w,e*side))));if(!insideOriginalEnvelope(s,pt)||solidList.some(o=>pt.every((v,i)=>v>=o.b[i]&&v<=o.b[i+3])&&inPart(o.p,pt))){ok=false;break;}}
   if(ok){f.chargeDepth=cd;return true;}}return false;};
 // One fitting cast onto the outermost surface along its axis. Armour plates take
 // no fittings, so a probe that lands on a plate (or finds no surface) is refused.
 const tryMount=(kind,p,axis,zone,o={})=>{const f={id:s.nextId++,k:kind,p:presetStationPoint(s,kind,p,axis,o),a:axis,ped:0,base:0,low:0,float:false,batteryZone:zone,...o};mountFit(s,f);const why=f._onPlate?'plate':f.float?'float':!plantFits(f)?'plant':'';if(opt.dbg)opt.dbg.push([kind,zone,p.map(Math.round).join(','),why||'ok',f.p.map(Math.round).join(',')]);if(why){s.nextId--;return null;}return f;};
 const clearOf=(f,list)=>list.every(g=>Math.hypot(f.p[0]-g.p[0],f.p[1]-g.p[1],f.p[2]-g.p[2])>=((FITS[f.k]?.fm||10)+(FITS[g.k]?.fm||10))*.5+2);
 // n fittings over candidate stations: dorsal ('top') and ventral ('bottom') rows
 // take |z| offsets and mount as mirrored pairs (0 = centreline); 'beam' rows take
 // heights and mount one a side. Stations on plates or crowding others are skipped.
 const spread=(kind,n,mode,zone,xs,offs,o={})=>{let got=0;
  for(const off of offs)for(const x of xs){if(got>=n)break;
   const ps=mode==='beam'?[[[x,off,400],4],[[x,off,-400],5]]:(off?[1,-1]:[1]).map(sg=>[[x,0,sg*off],mode==='top'?2:3]);
   if(got+ps.length>n)continue;const fs=[];
   for(const [p,a] of ps){const f=tryMount(kind,p,a,zone+(ps.length>1?(p[2]>0?'-stbd':'-port'):''),o);if(!f||!clearOf(f,s.fits.concat(fs)))break;fs.push(f);}
   if(fs.length<ps.length)continue;s.fits.push(...fs);got+=fs.length;}
  if(got<n){if(opt.dbg){opt.dbg.push(['SHORT',kind,zone,got,n]);return;}throw new Error('作例の砲座が不足しています: '+kind+' '+zone+' '+got+'/'+n);}};
 const range=(a,b,st)=>{const r=[];for(let x=a;x<=b+1e-6;x+=st)r.push(x);return r;};
 const mr=(a,b,st)=>range(M(a),M(b),st);
 // Pods seat on the first wall hit among a few probe heights.
 const podAt=(kind,host,o,dir)=>{let err='取付面がありません';for(const dy of [0,-4,4,-8,8,-12,12,-16,16])for(const dz of [0,-6,6,-12,12]){const q0=[o[0],o[1]+dy,o[2]+(dir[2]?0:dz)];const hit=host?rayPart(q0,dir,host):rayStructs(s,sub(q0,mul(dir,800)),dir);if(!hit)continue;const r=placeFit(s,kind,hit.p,hit.n,0,false);if(r.fit){r.fit.commandDepth=7;r.fit.commandHeight=5;return r.fit;}err=r.err;}throw new Error('艦橋ポッド '+kind+': '+err);};
 // v24 The measured structures differ from the hand-built ones: try the authored point first, then step along the ship.
 const pod=(kind,host,o,dir)=>{let last;for(const dx of [0,-30,30,-60,60,-100,100,-150,150,-200,200])try{return podAt(kind,host,[o[0]+dx,o[1],o[2]],dir);}catch(e){last=e;}throw last;};

 // The main bridge pod looks forward from the nose of the tower head, through the viewport band; the forward
 // command post on the bow ridge (the Invisible Hand's bridge in Revenge of the Sith) takes the combat pod.
 const ridge=null,glass=null,box83=null;
 pod('podBridge',glass,[M(200),M(312.2),0],[-1,0,0]);
 pod('podCombat',ridge,[M(930),Y(162),M(40)],[0,0,-1]);
 pod('podAir',box83,[M(560),Y(180),0],[-1,0,0]);
 syncAviationSurfaces(s);s._lockedCache=cache(s);
 try{withFrozenStructures(()=>{
  if(!dn){
  // Fourteen triple 200 TT balls replace the carrier's former ventral main
  // batteries; dual-purpose, flak, PD, missile and tractor seats retain their counts.
  spread('monCal200Triple',14,'bottom','ventral-quad',range(330,1040,26),[60,45,75,30,88]);
  // The two bow ion cannons remain omitted, matching the upstream refit.
  // Thirty-four spherical triple dual-purpose guns on both faces.
  spread('monCalPD',16,'top','dorsal-laser',range(540,1040,16),[20,34,48,8,60]);
  spread('monCalPD',18,'bottom','ventral-laser',range(300,1040,16),[15,98,22,105,8]);
  // Twelve spherical triple flak/PD guns on the bow sides.
  spread('monCalPD',12,'beam','flak',range(540,1020,15),[Y(130),Y(116),Y(104),Y(142)]);
  // 102 proton torpedo launchers in 34 banks of three: bow sides and dorsal
  spread('msl',20,'beam','side-torpedo',range(545,1020,14),[Y(124),Y(110),Y(136),Y(98)]);
  spread('msl',14,'top','dorsal-torpedo',range(545,1010,20),[14,28,42,56,0]);
  // Twelve spherical triple PD guns: ventral and dorsal-aft.
  spread('monCalPD',8,'bottom','ventral-pd',range(300,980,30),[70,85,55]);
  spread('monCalPD',4,'top','dorsal-aft-pd',range(280,500,12),[0,20]);
  // tractor beam projectors, ventral
  spread('trc',4,'bottom','tractor',range(500,960,25),[55,70,40,85]);
  }else{
  // Dreadnought: fourteen triple 200 TT balls beneath the hull.
  spread('monCal200Triple',14,'bottom','ventral-quad',mr(330,1040,22),[M(60),M(45),M(75),M(30),M(88)]);
  // The two bow ion cannons remain omitted, matching the upstream refit.
  // Thirty-four single 80 TT balls, dorsal and ventral.
  spread('monCal80',16,'top','dorsal-laser',mr(540,1040,16),[M(20),M(34),M(48),M(8),M(60)]);
  spread('monCal80',18,'bottom','ventral-laser',mr(300,1040,16),[M(15),M(98),M(22),M(105),M(8)]);
  // 102 proton torpedo launchers in 34 banks of three: bow sides and dorsal
  spread('msl',20,'beam','side-torpedo',mr(545,1020,14),[Y(124),Y(110),Y(136),Y(98)]);
  spread('msl',14,'top','dorsal-torpedo',mr(545,1010,20),[M(14),M(28),M(42),M(56),0]);
  // Twelve spherical triple flak/PD guns on the bow sides.
  spread('monCalPD',12,'beam','flak',mr(540,1020,15),[Y(130),Y(116),Y(104),Y(142)]);
  // Twelve spherical triple PD guns: ventral and dorsal-aft.
  spread('monCalPD',8,'bottom','ventral-pd',mr(300,980,30),[M(70),M(85),M(55)]);
  spread('monCalPD',4,'top','dorsal-aft-pd',mr(280,500,12),[0,M(20)]);
  // 10 heavy tractor beam emitters, port and starboard under the hull
  spread('trc',10,'bottom','tractor',mr(500,960,12),[M(55),M(70),M(40),M(85)]);
  }
 });}finally{delete s._lockedCache;}
 if(opt.stage==='fitted'){delete s._building;return s;}

 if(opt.stage==='shape'){delete s._building;return s;}
 // ---- compartments packed into the measured hull and structures ----
 for(const [kind,label,c,size,role,mirror] of D.rooms){const o={room:dn?size.map(M):size};if(typeof role==='string')o.airRole=role;placePart(s,kind,dn?c.map(M):c,dn?M(30):30,{label,...o},mirror===1||role===1);}
 // v19.1: the dreadnought hands most posts to automation (droid control) so its crew fits beside the conduits.
 if(dn)placePart(s,'automation',[1511,245,101],30,{label:'艦内運用の自動化装置',room:[299,42,21]},true);
 // v24 The two lower vehicle bays are the heavy lift platforms: they lower vehicles through the keel on
 // plain (unshielded) elevator doors. A machinery block separates them from the hangar decks, whose only
 // ray-shielded mouths are the beam openings of the through-slot above.
 for(const label of ['MTT・装甲車両格納区画（重量物昇降台） 2','MTT・装甲車両格納区画（重量物昇降台） 3']){const bay=s.parts.find(p=>p.label===label);if(bay)openBay(s,bay,'bottom','open');}
 if(opt.stage==='rooms'){delete s._building;return s;}
 // Canon complement: 120 Vulture droids, 120 droid tri-fighters, 10 Hyena bombers;
 // HMP gunships and Sheathipede shuttles are a game setting. 48,247 troops.
 s.airWings=(dn?PROV_DN_AIR:PROV_AIR).map(r=>({...r}));s.groundForces=normalizeGroundForces(dn?PROV_DN_GROUND:PROV_GROUND);
 delete s._building;adoptEquipment(s,true);remount(s);
 // v22 No broadside casemates: the canon lists have no guns beyond those above (v14 added them).
 syncCompartments(s);
 return s;

}
