 // (the trunk, the bridge head and the communications boom aft of it; the bridge's stepped forward decks and their viewports)
 const SP=SUBJ_SPAR,glass={skin:'plain',paint:SUBJ_GLASS};
 tidy(k.loftX('艦尾スパー（主艦橋塔の支柱）',SP.trunk,{corner:.2,paint:SUBJ_PANEL}));
 tidy(k.loftX('主艦橋頭部（艦尾スパー頂部・多層構造）',SP.head,{corner:.3,paint:SUBJ_GREY}));
 tidy(k.loftX('艦尾の通信アレイ（主艦橋頭部の後方ブーム）',SP.boom,{corner:.15,paint:SUBJ_PANEL}));
 tidy(k.loftX('主艦橋の前面下層甲板',SP.low,{corner:.1,paint:SUBJ_GREY}));
 tidy(k.loftX('主艦橋の前面中層甲板（艦橋本体）',SP.mid,{corner:.15,paint:SUBJ_GREY}));
 tidy(k.loftX('主艦橋の展望窓（中層・前面と両舷）',SP.glassMid,{corner:.1,...glass}));
 tidy(k.loftX('主艦橋の前面窓（下層）',SP.glassLow,{corner:.1,...glass}));
 k.box('主艦橋の前面窓（上層）',[606.2,827,-16],[607.2,834,16],{corner:.1,...glass});
