 for(const sg of [1,-1]){const h=part('hion','ハイパーイオン砲（'+(sg>0?'右舷':'左舷')+'）',[3060.4,289.4,sg*546.2],310.8,{reactor:gen.id});h.reactor=gen.id;}
 const aux=part('aux','副動力プラント（廃熱回収）',[1700,230,0],SUBJ_AUX_D);
 D.nozzles.forEach(([x0,x1,y,z,prof],i)=>{const r=Math.max(...prof.map(p=>p[1])),d=2*r*.94;
  const len=SUBJ_DRIVE_K[i]*(x1-x0);part('engine','亜光速推進機関',[x0+len/2,y,z],d,{dir:[-1,0,0],nozzleLength:len,bodyLength:2,bodyRadius:.4,reactor:aux.id},true);});
 // The feeds from the plant to the drives break the keel over x 1500-1640, so two longitudinal girders inside the
